triple A, B, C, O;

A = (3,0,0);
B = (0,4,0);
C = (0,0,2);
O = (0,0,0);

draw(O--(5,0,0));
draw(O--(0,5,0));
draw(O--(0,0,3));
draw(A--B--C--cycle);

label("$A$", A, S);
label("$B$", B, S);
label("$C$", C, NW);
label("$O$", O, S);
label("$b$", (O + B)/2, N);
